import { MeshBasicNodeMaterial } from 'three/webgpu';
import { vec3, mix, smoothstep, uv } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, BoxGeometry, CircleGeometry } = ctx.THREE;
  const root = new Group();
  const resources = [];
  const primitiveResults = [];
  const timelines = [];
  let alive = true;

  root.userData.handlers = {};

  const backdropMaterial = new MeshBasicNodeMaterial();
  backdropMaterial.colorNode = mix(
    vec3(0.043, 0.043, 0.063),
    vec3(0.086, 0.086, 0.114),
    smoothstep(0.0, 1.0, uv().y)
  );

  const backdrop = new Mesh(
    new PlaneGeometry(7, 6),
    backdropMaterial
  );
  backdrop.position.z = -2.5;
  backdrop.renderOrder = -10;
  root.add(backdrop);
  resources.push(backdrop.geometry, backdrop.material);

  const contactMaterial = new MeshBasicNodeMaterial({
    color: 0x000000,
    transparent: true,
    opacity: 0.46,
    depthWrite: false
  });

  const contact = new Mesh(
    new CircleGeometry(1.65, 48),
    contactMaterial
  );
  contact.rotation.x = -Math.PI / 2;
  contact.position.set(0, -0.94, -0.08);
  contact.scale.set(1.0, 0.42, 1.0);
  contact.renderOrder = -1;
  root.add(contact);
  resources.push(contact.geometry, contact.material);

  const card = new Group();
  card.position.set(0, -0.08, 0.08);
  card.scale.set(0.985, 0.985, 0.985);
  root.add(card);

  const surfaceMaterial = new MeshBasicNodeMaterial({
    color: 0xe8ecf2
  });

  const surface = new Mesh(
    new PlaneGeometry(2.75, 1.72),
    surfaceMaterial
  );
  surface.renderOrder = 2;
  card.add(surface);
  resources.push(surface.geometry, surface.material);

  const frameMaterial = new MeshBasicNodeMaterial({
    color: 0x16161d
  });

  const frameThickness = 0.045;
  const framePieces = [
    [2.84, frameThickness, 0.035, 0, 0.885],
    [2.84, frameThickness, 0.035, 0, -0.885],
    [frameThickness, 1.72, 0.035, -1.3975, 0],
    [frameThickness, 1.72, 0.035, 1.3975, 0]
  ];

  for (const [width, height, depth, x, y] of framePieces) {
    const piece = new Mesh(
      new BoxGeometry(width, height, depth),
      frameMaterial
    );
    piece.position.set(x, y, 0.035);
    piece.renderOrder = 3;
    card.add(piece);
    resources.push(piece.geometry);
  }
  resources.push(frameMaterial);

  const accentMaterial = new MeshBasicNodeMaterial({
    color: 0xff2a38
  });

  const accentRail = new Mesh(
    new BoxGeometry(0.055, 1.18, 0.045),
    accentMaterial
  );
  accentRail.position.set(-1.225, 0, 0.075);
  accentRail.renderOrder = 4;
  card.add(accentRail);
  resources.push(accentRail.geometry, accentMaterial);

  const lowerDepthMaterial = new MeshBasicNodeMaterial({
    color: 0x0b0b10
  });

  const lowerDepth = new Mesh(
    new BoxGeometry(2.32, 0.035, 0.09),
    lowerDepthMaterial
  );
  lowerDepth.position.set(0.12, -0.79, -0.01);
  lowerDepth.renderOrder = 1;
  card.add(lowerDepth);
  resources.push(lowerDepth.geometry, lowerDepth.material);

  const textItems =
    config.textContent ??
    config.intent?.visualSpec?.textContent ??
    [];

  for (const item of textItems) {
    if (!item || typeof item.text !== 'string' || !ctx.fontAtlas) continue;

    const textObject = ctx.fontAtlas.createText(item.text, {
      fontSize: item.typography?.fontSize,
      color: item.role === 'accent' ? '#ff2a38' : '#e8ecf2',
      align: item.typography?.align ?? 'left',
      maxWidthPx: item.typography?.maxWidthPx,
      letterSpacingPx: item.typography?.letterSpacingPx
    });

    textObject.position.set(
      item.position?.x ?? -0.92,
      item.position?.y ?? 0,
      0.11
    );
    card.add(textObject);
  }

  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((texture) => {
      if (!alive) {
        texture.dispose?.();
        return;
      }

      if (ctx.THREE.SRGBColorSpace) {
        texture.colorSpace = ctx.THREE.SRGBColorSpace;
      }
      texture.anisotropy = Math.min(
        texture.anisotropy ?? 1,
        ctx.renderer?.capabilities?.getMaxAnisotropy?.() ?? 4
      );
      surfaceMaterial.map = texture;
      surfaceMaterial.needsUpdate = true;
      resources.push(texture);
    });
  }

  const entrance = gsap.timeline();
  entrance.fromTo(
    card.scale,
    { x: 0.96, y: 0.96, z: 0.96 },
    {
      x: 1,
      y: 1,
      z: 1,
      duration: 0.7,
      ease: 'power3.out'
    }
  );
  timelines.push(entrance);

  const primitives = config.cinematicPrimitives ?? [];
  for (const primitive of primitives) {
    const handler = ctx.primitives?.[primitive.name];
    if (typeof handler !== 'function') continue;

    const result = handler(root, primitive.params);
    if (result) {
      primitiveResults.push(result);
      if (result.timeline) timelines.push(result.timeline);
    }
  }

  root.userData.cleanup = () => {
    alive = false;

    for (const timeline of timelines) {
      timeline?.kill?.();
    }

    for (const result of primitiveResults) {
      result?.cleanup?.();
    }

    for (const resource of resources) {
      resource?.dispose?.();
    }

    root.clear();
  };

  return root;
}
